import asyncio
import os

import pytest

from telco_support_agent.app import AskGraph

pytestmark = pytest.mark.skipif(
    not os.environ.get("RUN_LIVE_SMOKE"),
    reason="live smoke test; set RUN_LIVE_SMOKE=1 (needs OPENAI_API_KEY and network)",
)


@pytest.fixture(scope="module")
def graph() -> AskGraph:
    from telco_support_agent.app import production_graph

    return asyncio.run(production_graph())


@pytest.mark.parametrize(
    ("question", "expected_outcome"),
    [
        ("Hoe stap ik over naar Telco?", "grounded"),
        ("What TV packages does Telco offer?", "grounded"),  # cross-lingual
        ("What is the capital of France?", "insufficient_context"),
        ("Wat kost een internetabonnement van 1 Gbit/s per maand?", "insufficient_context"),
    ],
)
def test_request_outcome(graph: AskGraph, question: str, expected_outcome: str) -> None:
    result = asyncio.run(graph.ainvoke({"question": question}))

    assert result["outcome"] == expected_outcome
    if expected_outcome == "grounded":
        assert result["sources"], "a grounded answer must carry at least one source"
    else:
        assert result["sources"] == []

